import React, { useEffect, useState } from "react";
import './CarFilter.css';

export default function CarFilter() {

    const [brandFilter, setBrandFilter] = useState(null)
    const [modelFilter, setModelFilter] = useState(null)
    const [typeFilter, setTypeFilter] = useState(null)


    const [cars, setCars] = useState([])

    useEffect(() => {
        const fetchCars = async () => {

            let url = "http://localhost:5000/cars?";

            if (brandFilter) {
                url += `brand=${brandFilter}&`;
            }

            if (modelFilter) {
                url += `model=${modelFilter}&`;
            }

            if (typeFilter) {
                url += `type=${typeFilter}&`;
            }

            const response = await fetch(url);

            const data = await response.json();

            setCars(data)
        }

        fetchCars();
    },[brandFilter, modelFilter, typeFilter])

    useEffect(() =>{
        console.log(cars)
    },[cars])

    useEffect(() => {
        console.log(brandFilter)
    },[])

    return (
        <div className="root">
            <div className="filter">
                <div className="brand">
                    <h3>--- Marque ---</h3>
                    <div className="input">
                        <input type="checkbox" checked={brandFilter === 'BMW'} onClick={() => setBrandFilter('BMW')}/>
                        <label>BMW</label>
                    </div>
                    <div className="input">
                        <input type="checkbox" checked={brandFilter === 'Citroen'} onClick={() => setBrandFilter('Citroen')}/>
                        <label>Citroen</label>
                    </div>
                    <div className="input">
                        <input type="checkbox" checked={brandFilter === 'Renault'} onClick={() => setBrandFilter('Renault')}/>
                        <label>Renault</label>
                    </div> 
                </div>
                <div>
                    <h3>--- Modèle ---</h3>
                    <div className="input">
                        <input type="checkbox" />
                        <label>label</label>
                    </div>
                    <div className="input">
                        <input type="checkbox"/>
                        <label>label</label>
                    </div>
                    <div className="input">
                        <input type="checkbox"/>
                        <label>label</label>
                    </div>  
                </div>
                <div>
                    <h3>--- Type ---</h3>
                    <div className="input">
                        <input type="checkbox"/>
                        <label>label</label>
                    </div>
                    <div className="input">
                        <input type="checkbox"/>
                        <label>label</label>
                    </div>
                    <div className="input">
                        <input type="checkbox"/>
                        <label>label</label>
                    </div> 
                </div>
            </div>

            <div className="tab">
                <class className="titles">
                    <div className="titleCol"> marque </div>
                    <div className="titleCol"> modèle </div>
                    <div className="titleCol"> type</div>
                </class>
                <div className="car">
                    {cars.map((car, index) => (
                        <div key={car.id} className={`${"elements"} ${index % 2 === 0 ? "grayBackground" : ''}`} >
                            <div className="col">{car.brand}</div>
                            <div className="col">{car.model}</div>
                            <div className="col">{car.type} </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    )
};
